local function fields(s)
 local b={};local i=1
 while i<=#s do
  local v=s:byte(i);i=i+1
  if v>=192 then v=(v-192)*64+s:byte(i)-128;i=i+1 end
  b[#b+1]=v-32
 end
 return b
end
